let focusState=FocusClock.create(),focusSound=true,focusAudio=null,focusImmersive=false;
try{const saved=JSON.parse(localStorage.getItem('creator-focus-clock-v1'));if(FocusClock.valid(saved))focusState=saved}catch{}
function saveFocus(){try{localStorage.setItem('creator-focus-clock-v1',JSON.stringify(focusState))}catch{}}
function focusChime(){if(!focusSound||!focusAudio)return;try{[523.25,659.25,783.99,1046.5].forEach((f,i)=>{const osc=focusAudio.createOscillator(),gain=focusAudio.createGain(),at=focusAudio.currentTime+i*.15;osc.type='sine';osc.frequency.value=f;osc.connect(gain);gain.connect(focusAudio.destination);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.1,at+.025);gain.gain.exponentialRampToValueAtTime(.001,at+.8);osc.start(at);osc.stop(at+.85)})}catch{}}
