function settleFocus(){const next=FocusClock.tick(focusState);if(next!==focusState){focusState=next;saveFocus();if(activeProfile==='mads'){focusChime();toast('✦ Fokus-session klaret. Godt arbejde!');if(view==='timer'){$('#focusTimer').classList.add('focusFinished');setTimeout(()=>$('#focusTimer').classList.remove('focusFinished'),1800)}}}}
function renderFocus(){const marks=Array.from({length:60},(_,i)=>{const a=i*Math.PI/30,x=Math.sin(a),y=-Math.cos(a),inner=i%5===0?163:167;return `<line x1="${180+x*inner}" y1="${180+y*inner}" x2="${180+x*171}" y2="${180+y*171}" class="${i%5===0?'major':''}"/>`}).join('');$('#focusTimer').innerHTML=`<div class="focusTop"><span class="focusEyebrow">◌ FOCUS MODE</span><div><button class="focusIcon" id="focusAudio" aria-pressed="${focusSound}">${focusSound?'♫ Lyd til':'♫ Lyd fra'}</button><button class="focusIcon" id="focusExpand" aria-pressed="${focusImmersive}">${focusImmersive?'↙ Tilbage':'↗ Kun fokus'}</button></div></div><div class="focusStage"><div class="focusHalo"></div><div class="focusDial"><svg viewBox="0 0 360 360" aria-hidden="true"><g class="focusTicks">${marks}</g><circle class="focusTrack" cx="180" cy="180" r="145"/><circle class="focusArc" id="focusArc" cx="180" cy="180" r="145" pathLength="100" stroke-dasharray="100"/></svg><div class="focusCenter"><span class="focusMode" id="focusMode">KLAR TIL FOKUS</span><strong id="focusTime" role="timer" aria-live="off">25:00</strong><span class="focusCaption" id="focusCaption">MINUTTER TIL DIG OG DIT ARBEJDE</span></div></div></div><div class="focusSettings"><div class="focusPresets">${[15,25,45,60].map(n=>`<button data-focus-minutes="${n}">${n} min</button>`).join('')}</div><label class="focusCustom">Din tid<input type="number" id="focusMinutes" min="1" max="240" step="1" value="${Math.round(focusState.duration/60000)}" inputmode="numeric" aria-label="Antal minutter"><span>min</span></label></div><div class="focusActions"><button id="focusReset" class="focusReset" aria-label="Nulstil timer">↺</button><button id="focusStart" class="focusStart">▶ Start fokus</button><span class="focusSpacer"></span></div><p id="focusFeedback" class="focusFeedback" role="status"></p><div class="focusBottom"><span class="focusDot"></span><span id="focusBottomLabel">FIND DIT TEMPO</span></div>`;updateFocus()}
function updateFocus(){if(!$('#focusTime'))return;const remaining=FocusClock.remaining(focusState),seconds=Math.ceil(remaining/1000),minutes=Math.floor(seconds/60),fraction=Math.max(0,Math.min(1,remaining/focusState.duration));$('#focusTime').textContent=String(minutes).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('#focusArc').style.strokeDashoffset=String((1-fraction)*100);$('#focusMode').textContent=focusState.completed?'SESSION KLARET':focusState.running?'DU ER I FOKUS':remaining<focusState.duration?'PÅ PAUSE':'KLAR TIL FOKUS';$('#focusCaption').textContent=focusState.completed?'GODT ARBEJDE. TRÆK VEJRET.':'MINUTTER TIL DIG OG DIT ARBEJDE';$('#focusStart').textContent=focusState.completed?'↻ En runde mere':focusState.running?'Ⅱ Pause':remaining<focusState.duration?'▶ Fortsæt':'▶ Start fokus';$('#focusMinutes').disabled=focusState.running;document.querySelectorAll('[data-focus-minutes]').forEach(b=>{b.disabled=focusState.running;b.classList.toggle('selected',Number(b.dataset.focusMinutes)*60000===focusState.duration)});$('#focusTimer').classList.toggle('isRunning',focusState.running);$('#focusTimer').classList.toggle('isComplete',focusState.completed);$('#focusBottomLabel').textContent=focusState.completed?'DU GJORDE PLADS TIL FREMSKRIDT':focusState.running?'ÉN TING. FULDT FOKUS.':remaining<focusState.duration?'TAG DEN TID, DU HAR BRUG FOR':'FIND DIT TEMPO';const badge=document.querySelector('[data-view="timer"] span');if(badge)badge.textContent=focusState.running?'Fokus · '+$('#focusTime').textContent:'Fokustimer'}
function setFocusMinutes(value){const min=Number(value);if(!Number.isInteger(min)||min<1||min>240){$('#focusFeedback').textContent='Vælg mellem 1 og 240 hele minutter.';return false}if(focusState.running)return false;focusState=FocusClock.create(min);saveFocus();$('#focusMinutes').value=String(min);$('#focusFeedback').textContent='';updateFocus();return true}
$('#focusTimer').onchange=e=>{if(e.target.id==='focusMinutes'&&activeProfile==='mads')setFocusMinutes(e.target.value)};
$('#focusTimer').onclick=e=>{if(activeProfile!=='mads')return;const preset=e.target.closest('[data-focus-minutes]');if(preset){setFocusMinutes(preset.dataset.focusMinutes);return}if(e.target.closest('#focusStart')){settleFocus();if(focusState.running)focusState=FocusClock.pause(focusState);else{if(!$('#focusMinutes').checkValidity()){$('#focusFeedback').textContent='Vælg mellem 1 og 240 hele minutter.';return}prepareFocusAudio();focusState=FocusClock.start(focusState)}saveFocus();updateFocus();return}if(e.target.closest('#focusReset')){focusState=FocusClock.reset(focusState);saveFocus();$('#focusFeedback').textContent='';updateFocus()}if(e.target.closest('#focusAudio')){focusSound=!focusSound;if(focusSound)prepareFocusAudio();$('#focusAudio').textContent=focusSound?'♫ Lyd til':'♫ Lyd fra';$('#focusAudio').setAttribute('aria-pressed',String(focusSound))}if(e.target.closest('#focusExpand')){focusImmersive=!focusImmersive;document.body.classList.toggle('focusImmersive',focusImmersive);$('#focusExpand').textContent=focusImmersive?'↙ Tilbage':'↗ Kun fokus';$('#focusExpand').setAttribute('aria-pressed',String(focusImmersive))}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focusImmersive){focusImmersive=false;document.body.classList.remove('focusImmersive');if(view==='timer')renderFocus()}});
const beforeFocusRender=render;render=function(){beforeFocusRender();const active=view==='timer'&&activeProfile==='mads';$('#focusTimer').hidden=!active;$('#newVideo').hidden=active;if(!active){focusImmersive=false;document.body.classList.remove('focusImmersive');return}$('#aiPlanner').hidden=true;$('#calendar').hidden=true;$('#list').hidden=true;document.querySelectorAll('main>.sectionline').forEach(n=>n.hidden=true);$('.hero').hidden=true;$('.toolbar').style.display='none';$('#undoDelete').hidden=true;$('#title').textContent='Tid til fordybelse.';$('#subtitle').textContent='';settleFocus();renderFocus()};
setInterval(()=>{settleFocus();if(view==='timer'&&activeProfile==='mads')updateFocus()},250);document.addEventListener('visibilitychange',()=>{settleFocus();if(view==='timer'&&activeProfile==='mads')updateFocus()});render();

let syncShadow=new Map(),syncVersions=new Map(),syncQueue=[],syncWorking=false,syncUser=null;
function normalizedVideo(v){return {id:v.id,title:v.title,intro:v.intro||'',concept:v.concept||'',channel:v.channel||null,dates:v.dates,done:v.done,publishDate:v.publishDate||'',plannedDates:v.plannedDates||[null,null,null],...(v.deletedAt?{deletedAt:v.deletedAt}:{})}}
function signature(v){return JSON.stringify(normalizedVideo(v))}
function allLocalVideos(){return [...videos,...deletedVideos]}
function persistQueue(){try{localStorage.setItem('creator-sync-pending-v1',JSON.stringify({email:syncUser,operations:syncQueue}))}catch{}}
function setSyncStatus(text,error=false){if($('#videoDetail').open&&$('#detailNotice').dataset.statusSave==='true')$('#detailNotice').textContent=text==='Synkroniseret'?'Status gemt automatisk ✓':text==='Gemmer…'?'Gemmer status…':text;$('#syncStatus').textContent=text;$('#syncStatus').classList.toggle('syncError',error)}
function applyShared(snapshot){videos=snapshot.videos.filter(v=>!v.deletedAt);deletedVideos.splice(0,deletedVideos.length,...snapshot.videos.filter(v=>v.deletedAt));syncVersions=new Map(snapshot.videos.map(v=>[v.id,v._version]));syncShadow=new Map(allLocalVideos().map(v=>[v.id,signature(v)]));localSave();if(!$('#modal').open&&!$('#briefModal').open&&!$('#videoDetail').open)render()}
const localSave=save;save=function(){localSave();if(!workspaceReady)return;for(const v of allLocalVideos()){const sig=signature(v);if(syncShadow.get(v.id)===sig)continue;const waiting=syncQueue.filter(op=>op.video.id===v.id).length;syncQueue.push({video:JSON.parse(sig),baseVersion:(syncVersions.get(v.id)||0)+waiting});syncShadow.set(v.id,sig)}persistQueue();if(syncQueue.length){setSyncStatus('Gemmer…');drainSync()}};
async function sharedRequest(body){const r=await fetch('/api/workspace',{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(15000)});let data;try{data=await r.json()}catch{throw Error('Serveren kunne ikke svare. Prøv igen.')}if(!r.ok){const err=Error(data.error||'Ændringen kunne ikke gemmes.');err.status=r.status;throw err}return data}
async function drainSync(){if(syncWorking||!workspaceReady||!syncQueue.length)return;syncWorking=true;try{while(syncQueue.length){const op=syncQueue[0];const result=await sharedRequest({action:'save',...op});syncVersions.set(op.video.id,result.version);syncQueue.shift();persistQueue()}setSyncStatus('Synkroniseret')}catch(err){if([400,403,409].includes(err.status)){try{localStorage.setItem('creator-sync-recovery-v1',JSON.stringify(syncQueue))}catch{}syncQueue=[];persistQueue();setSyncStatus('Ændring afvist — prøv igen',true);toast(err.message);try{applyShared(await sharedRequest())}catch{}}else{setSyncStatus('Offline · ændringer afventer',true)}}finally{syncWorking=false}}
async function refreshShared(){if(!workspaceReady||$('#modal').open||$('#briefModal').open||$('#videoDetail').open||boardDragging)return;if(syncQueue.length){await drainSync();return}if(syncWorking)return;syncWorking=true;try{const snapshot=await sharedRequest();if(syncQueue.length)return;if(snapshot.user.role!==workspaceRole){location.reload();return}const incoming=JSON.stringify(snapshot.videos.map(v=>[v.id,v._version]));const existing=JSON.stringify([...syncVersions]);if(incoming!==existing)applyShared(snapshot);setSyncStatus('Synkroniseret')}catch{setSyncStatus('Forbindelse afbrudt',true)}finally{syncWorking=false}}
async function startShared(){try{await sharedRequest({action:'initialize',videos:[]});await bootShared()}catch(err){$('#syncMessage').textContent=err.message}}
async function bootShared(){workspaceReady=false;if($('#profilePicker').open)$('#profilePicker').close();if(!$('#syncGate').open)$('#syncGate').showModal();$('#syncRetry').hidden=true;$('#startShared').hidden=true;try{let snapshot=await sharedRequest();workspaceRole=snapshot.user.role;syncUser=snapshot.user.email;
 if(!snapshot.initialized){if(workspaceRole==='admin'&&originalLocalWorkspace){let legacy;try{legacy=JSON.parse(originalLocalWorkspace)}catch{}if(Array.isArray(legacy)){try{localStorage.setItem('creator-before-cloud-backup-v1',originalLocalWorkspace)}catch{}await sharedRequest({action:'initialize',videos:legacy.map(normalizedVideo)});snapshot=await sharedRequest()}else throw Error('Den lokale kalender kunne ikke overføres. Den er bevaret i browseren.')}else{$('#syncMessage').textContent=workspaceRole==='admin'?'Denne browser har ingen tidligere kalender. Åbn først appen i browseren med de eksisterende videoer for at overføre dem, eller start tomt her.':'Ejeren skal først overføre den eksisterende kalender til fælles lagring.';$('#startShared').hidden=workspaceRole!=='admin';return}}
 applyShared(snapshot);let pending;try{pending=JSON.parse(localStorage.getItem('creator-sync-pending-v1'))}catch{}if(pending?.email===syncUser&&Array.isArray(pending.operations)){syncQueue=pending.operations.filter(op=>{const v=allLocalVideos().find(v=>v.id===op.video?.id);return !v||signature(v)!==signature(op.video)});for(const op of syncQueue){const target=op.video.deletedAt?deletedVideos:videos,other=op.video.deletedAt?videos:deletedVideos;const oi=other.findIndex(v=>v.id===op.video.id);if(oi>=0)other.splice(oi,1);const i=target.findIndex(v=>v.id===op.video.id);if(i>=0)target[i]=op.video;else target.push(op.video)}syncShadow=new Map(allLocalVideos().map(v=>[v.id,signature(v)]))}
 workspaceReady=true;$('#syncGate').close();setSyncStatus('Synkroniseret');if(workspaceRole!=='admin'){activeProfile=workspaceRole;try{sessionStorage.setItem('creator-profile',activeProfile)}catch{}view=isManager()?'calendar':'today';$('#switchProfile').textContent='Log ud';$('#switchProfile').onclick=()=>{location.href='/signout-with-chatgpt?return_to=%2F'};$('#cancelProfile').hidden=true}else if(!activeProfile)showProfiles();render();if(workspaceRole!=='admin'){$('#switchProfile').textContent=(workspaceRole==='mads'?'Mads':'Patrick')+' · Log ud'}if(syncQueue.length)drainSync();
 }catch(err){$('#syncTitle').textContent='Workspace kunne ikke åbnes';$('#syncMessage').textContent=err.message;$('#syncRetry').hidden=false;setSyncStatus('Ikke forbundet',true)}}
