const beforeWeekRender=render;render=function(){beforeWeekRender();const active=view==='week';$('#weekOverview').hidden=!active;if(!active)return;const dates=weekDates(day);$('#dateLabel').textContent=shortDate(dates[0])+' – '+shortDate(dates[6])+' '+dates[6].slice(0,4);$('#weekOverview').innerHTML=dates.map(date=>{const tasks=videos.flatMap(v=>v.done.map((done,i)=>({done,date:plannedDate(v,i)}))).filter(t=>t.date===date),done=tasks.filter(t=>t.done).length,releases=videos.filter(v=>v.publishDate===date);return `<button class="weekDay ${date===today?'weekToday':''}" data-week-day="${date}"><span>${new Date(date+'T12:00:00').toLocaleDateString('da-DK',{weekday:'short'})}</span><strong>${new Date(date+'T12:00:00').getDate()}</strong><small>${done}/${tasks.length} opgaver</small><i style="--day-progress:${tasks.length?done/tasks.length*100:0}%"></i><small class="weekRelease">${releases.length?releases.length+' '+(releases.length===1?'udgivelse':'udgivelser'):'—'}</small></button>`}).join('');};
$('#weekOverview').onclick=e=>{const b=e.target.closest('[data-week-day]');if(!b)return;day=b.dataset.weekDay;view='today';filter='all';render()};render();
let briefEditing=null,detailVideoId=null,detailTab='title',boardDragging=false,lastBoardDrag=0,touchCardDrag=null;
function openBrief(v=null){briefEditing=v?.id||null;$('#briefChannel').value=channels.includes(v?.channel)?v.channel:'';$('#saveBrief').disabled=!channels.includes($('#briefChannel').value);$('#briefTitle').textContent=v?'Rediger videoens tekst':'Indsæt din videoidé';$('#saveBrief').textContent=v?'Gem tekst →':'Opret videokort →';$('#briefText').value=v?`Titel: ${v.title}\n\nIntro: ${v.intro||''}\n\nKoncept: ${v.concept||''}`:'';$('#briefError').textContent='';$('#briefPreview').hidden=true;$('#briefModal').showModal();$('#briefText').focus();previewBrief()}
function previewBrief(){const text=$('#briefText').value;if(!text.trim()){$('#briefPreview').hidden=true;$('#briefError').textContent='';return}const result=VideoBrief.parse(text);$('#briefPreview').hidden=Boolean(result.error);$('#briefError').textContent=result.error||'';if(!result.error){$('#briefPreviewTitle').textContent=result.title;$('#briefPreviewMeta').textContent=`Intro: ${result.intro.length} tegn · Koncept: ${result.concept.length} tegn`}}
$('#briefChannel').onchange=()=>{$('#saveBrief').disabled=!channels.includes($('#briefChannel').value)};$('#briefText').oninput=previewBrief;$('#closeBrief').onclick=()=>$('#briefModal').close();$('#briefForm').onsubmit=e=>{e.preventDefault();const channel=$('#briefChannel').value;if(!channels.includes(channel)){$('#briefError').textContent='Vælg en kanal, før du opretter videoen.';$('#briefChannel').focus();return}const brief=VideoBrief.parse($('#briefText').value);if(brief.error){$('#briefError').textContent=brief.error;return}let v;if(briefEditing){v=videos.find(v=>v.id===briefEditing);if(!v){$('#briefError').textContent='Videoen findes ikke længere.';return}Object.assign(v,brief,{channel})}else{v={id:crypto.randomUUID(),...brief,channel,publishDate:'',dates:[day,day,day],plannedDates:[null,null,null],done:[false,false,false]};videos.unshift(v)}save();$('#briefModal').close();filter='all';render();toast(briefEditing?'Videoens tekst er gemt ✓':'Videokort oprettet. Træk det til en dag i ugen.');};
function openVideoDetail(id){const v=videos.find(v=>v.id===id);if(!v)return;detailVideoId=id;detailTab='title';$('#detailTitle').textContent=v.title;$('#detailChannel').value=v.channel||'';$('#detailDate').value=v.publishDate||'';$('#detailNotice').textContent='';$('#detailNotice').dataset.statusSave='false';renderDetailStatus(v);renderDetailTab();$('#videoDetail').showModal()}
function renderDetailStatus(v){$('#detailStatus').innerHTML=names.map((name,i)=>`<button type="button" data-detail-step="${i}" ${isManager()?'disabled':''} aria-pressed="${v.done[i]}" class="detailStep ${v.done[i]?'isDone':''}">${v.done[i]?'✓':'○'} ${name}</button>`).join('')}
