$('#videoDetail').onclick=e=>{const step=e.target.closest('[data-detail-step]');if(step){if(isManager())return;const v=videos.find(v=>v.id===detailVideoId);if(!v)return;const i=Number(step.dataset.detailStep);v.done[i]=!v.done[i];if(v.done[i])celebrate(step,v.done.every(Boolean));$('#detailNotice').dataset.statusSave='true';$('#detailNotice').textContent='Gemmer status…';save();renderDetailStatus(v);render();return}const tab=e.target.closest('[data-detail-tab]');if(tab){detailTab=tab.dataset.detailTab;renderDetailTab()}};$('#videoDetail').addEventListener('keydown',e=>{if(!e.target.matches('[data-detail-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['title','intro','concept'],index=tabs.indexOf(detailTab);detailTab=e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(index+(e.key==='ArrowRight'?1:2))%3];renderDetailTab();$('#tab-'+detailTab).focus()});$('#closeDetail').onclick=()=>{$('#videoDetail').close();render()};$('#editBrief').onclick=()=>{const v=videos.find(v=>v.id===detailVideoId);$('#videoDetail').close();if(v)openBrief(v)};$('#detailSettings').onclick=()=>{const v=videos.find(v=>v.id===detailVideoId);$('#videoDetail').close();if(v)openModal(v)};$('#detailPlan').onsubmit=e=>{e.preventDefault();const v=videos.find(v=>v.id===detailVideoId);if(!v)return;const channel=$('#detailChannel').value,publishDate=$('#detailDate').value;if(channel&&!channels.includes(channel))return;v.channel=channel||null;v.publishDate=publishDate;save();$('#videoDetail').close();render();toast('Videoens plan er gemt ✓')};
function briefCard(v){return `<article class="briefCard ${v.done.every(Boolean)?'briefComplete':''}" draggable="true" data-card-id="${v.id}"><div class="briefCardTop"><span>${escape(channelLabel(v))}</span><button class="cardHandle" type="button" aria-label="Træk ${escape(v.title)} til en anden dag" tabindex="-1">⠿</button></div><button type="button" class="openBriefCard" data-open-video="${v.id}" aria-label="Åbn video: ${escape(v.title)}"><strong>${escape(v.title)}</strong><span class="briefCardSummary">${v.intro?'Intro og koncept':'Tilføj intro og koncept'} ↗</span></button><div class="briefCardSteps" aria-label="${v.done.filter(Boolean).length} af 3 trin klaret">${names.map((n,i)=>`<span class="${v.done[i]?'isDone':''}" title="${n}${v.done[i]?' klaret':' mangler'}">${v.done[i]?'✓':'○'} ${n}</span>`).join('')}</div></article>`}
function renderWeekBoard(){const dates=weekDates(day),matches=v=>filter==='all'||(filter==='done'?v.done.every(Boolean):!v.done.every(Boolean)),unplaced=videos.filter(v=>!v.publishDate&&matches(v));$('#weekOverview').innerHTML=`<div class="boardIntro"><span class="eyebrow">UGENS UDGIVELSER</span><small>Træk et kort til en dag · klik for at åbne videoen</small></div><div class="weekBoardScroll"><div class="weekBoardColumns">${dates.map(date=>{const cards=videos.filter(v=>v.publishDate===date&&matches(v));return `<section class="boardDay ${date===today?'boardToday':''}" data-drop-day="${date}" aria-label="${new Date(date+'T12:00:00').toLocaleDateString('da-DK',{weekday:'long',day:'numeric',month:'long'})}"><div class="boardDayHeader"><div><span>${new Date(date+'T12:00:00').toLocaleDateString('da-DK',{weekday:'short'})}</span><strong>${new Date(date+'T12:00:00').getDate()}</strong></div><span class="boardCount">${cards.length}</span></div><div class="boardCardStack">${cards.map(briefCard).join('')||'<div class="boardDropHint">Slip et videokort her</div>'}</div></section>`}).join('')}</div></div><section class="boardUnplaced" data-drop-day="unplaced"><div class="boardIntro"><span class="eyebrow">IKKE PLACERET <b>${unplaced.length}</b></span><button type="button" class="quiet" id="newBoardVideo">＋ Ny video</button></div><div class="unplacedCards">${unplaced.map(briefCard).join('')||'<p class="muted">Nye videokort lander her, indtil du giver dem en udgivelsesdag.</p>'}</div></section>`}
function moveBoardVideo(id,date){const v=videos.find(v=>v.id===id);if(!v)return;if(date!=='unplaced'&&!weekDates(day).includes(date))return;const target=date==='unplaced'?'':date;if(v.publishDate===target)return;v.publishDate=target;save();render();toast(target?'Udgivelsen er flyttet til '+shortDate(target)+' ✓':'Videoen er flyttet til Ikke placeret')}
let nativeCardId=null;
$('#weekOverview').ondragstart=e=>{const card=e.target.closest('[data-card-id]');if(!card)return;nativeCardId=card.dataset.cardId;boardDragging=true;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',nativeCardId);card.classList.add('cardDragging')};
$('#weekOverview').ondragover=e=>{const target=e.target.closest('[data-drop-day]');if(!target)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.boardDropActive').forEach(n=>n.classList.remove('boardDropActive'));target.classList.add('boardDropActive')};
function clearBoardDrag(){boardDragging=false;nativeCardId=null;document.querySelectorAll('.boardDropActive,.cardDragging').forEach(n=>{n.classList.remove('boardDropActive');n.classList.remove('cardDragging')})}
$('#weekOverview').ondrop=e=>{const target=e.target.closest('[data-drop-day]');e.preventDefault();const id=nativeCardId;clearBoardDrag();if(target&&id){lastBoardDrag=Date.now();moveBoardVideo(id,target.dataset.dropDay)}};$('#weekOverview').ondragend=clearBoardDrag;
$('#weekOverview').onclick=e=>{if(Date.now()-lastBoardDrag<350)return;if(e.target.closest('#newBoardVideo')){openBrief();return}const b=e.target.closest('[data-open-video]');if(b)openVideoDetail(b.dataset.openVideo)};
$('#weekOverview').addEventListener('pointerdown',e=>{const handle=e.target.closest('.cardHandle');if(!handle||e.pointerType==='mouse')return;e.preventDefault();const card=handle.closest('[data-card-id]');touchCardDrag={id:card.dataset.cardId,handle,startX:e.clientX,startY:e.clientY,ghost:null};handle.setPointerCapture(e.pointerId);boardDragging=true});
$('#weekOverview').addEventListener('pointermove',e=>{if(!touchCardDrag)return;e.preventDefault();if(!touchCardDrag.ghost&&Math.hypot(e.clientX-touchCardDrag.startX,e.clientY-touchCardDrag.startY)<8)return;if(!touchCardDrag.ghost){const ghost=document.createElement('div');ghost.className='touchCardGhost';ghost.textContent=videos.find(v=>v.id===touchCardDrag.id)?.title||'';document.body.append(ghost);touchCardDrag.ghost=ghost}touchCardDrag.ghost.style.left=e.clientX+'px';touchCardDrag.ghost.style.top=e.clientY+'px';document.querySelectorAll('.boardDropActive').forEach(n=>n.classList.remove('boardDropActive'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop-day]')?.classList.add('boardDropActive')});
function endTouchCard(e,cancel=false){if(!touchCardDrag)return;const drag=touchCardDrag,target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop-day]');drag.ghost?.remove();touchCardDrag=null;clearBoardDrag();if(!cancel&&drag.ghost&&target){lastBoardDrag=Date.now();moveBoardVideo(drag.id,target.dataset.dropDay)}}
$('#weekOverview').addEventListener('pointerup',e=>endTouchCard(e));$('#weekOverview').addEventListener('pointercancel',e=>endTouchCard(e,true));
const beforeBoardRender=render;render=function(){beforeBoardRender();$('#newVideo').hidden=view!=='week';$('#weekOverview').classList.toggle('weekBoard',view==='week');if(view!=='week')return;$('#list').hidden=true;document.querySelectorAll('main>.sectionline').forEach(n=>n.hidden=true);renderWeekBoard()};$('#newVideo').onclick=()=>{if(view==='week')openBrief()};
const beforeBoardListClick=$('#list').onclick;$('#list').onclick=e=>{const title=e.target.closest('.videoName h3');if(title){const edit=title.closest('.video').querySelector('[data-edit]');if(edit){openVideoDetail(edit.dataset.edit);return}}beforeBoardListClick(e)};
render();
